        "content": "/**\n * @plain-ui/tokens - base.css\n * \n * HTML5 Semantic Reset, Focus-Visible Outline Rings,\n * Typography Defaults, and Accessible Scrollbar Styling.\n *\n * Part of Plain UI Design System.\n */\n\n/* ==========================================================================\n   1. HTML5 SEMANTIC RESET & BOX-SIZING\n   ========================================================================== */\n\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n  border-width: 0;\n  border-style: solid;\n  border-color: var(--border, currentColor);\n}\n\nhtml {\n  -webkit-text-size-adjust: 100%;\n  -moz-tab-size: 4;\n  tab-size: 4;\n  font-family: var(--font-sans, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif);\n  font-feature-settings: normal;\n  font-variation-settings: normal;\n  line-height: var(--leading-normal, 1.5);\n  color: var(--foreground);\n  background-color: var(--background);\n  scroll-behavior: smooth;\n}\n\nbody {\n  min-height: 100vh;\n  min-height: 100dvh;\n  margin: 0;\n  line-height: inherit;\n  color: inherit;\n  background-color: inherit;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  text-rendering: optimizeLegibility;\n}\n\n/* Block display for HTML5 semantic elements */\narticle,\naside,\ndetails,\nfigcaption,\nfigure,\nfooter,\nheader,\nhgroup,\nmain,\nnav,\nsection,\nsummary {\n  display: block;\n}\n\n/* ==========================================================================\n   2. TYPOGRAPHY DEFAULTS\n   ========================================================================== */\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  font-weight: var(--font-weight-semibold, 600);\n  line-height: var(--leading-tight, 1.25);\n  color: var(--foreground);\n  text-wrap: balance;\n}\n\nh1 {\n  font-size: var(--font-size-4xl, 2.25rem);\n  letter-spacing: var(--tracking-tight, -0.025em);\n  font-weight: var(--font-weight-bold, 700);\n  margin-bottom: 0.75rem;\n}\n\nh2 {\n  font-size: var(--font-size-3xl, 1.875rem);\n  letter-spacing: var(--tracking-tight, -0.025em);\n  margin-bottom: 0.625rem;\n}\n\nh3 {\n  font-size: var(--font-size-2xl, 1.5rem);\n  letter-spacing: var(--tracking-tight, -0.025em);\n  margin-bottom: 0.5rem;\n}\n\nh4 {\n  font-size: var(--font-size-xl, 1.25rem);\n  margin-bottom: 0.5rem;\n}\n\nh5 {\n  font-size: var(--font-size-lg, 1.125rem);\n  margin-bottom: 0.375rem;\n}\n\nh6 {\n  font-size: var(--font-size-base, 1rem);\n  margin-bottom: 0.25rem;\n}\n\np {\n  line-height: var(--leading-relaxed, 1.625);\n  margin-bottom: 1rem;\n  text-wrap: pretty;\n}\n\np:last-child {\n  margin-bottom: 0;\n}\n\nsmall {\n  font-size: var(--font-size-sm, 0.875rem);\n}\n\nstrong,\nb {\n  font-weight: var(--font-weight-bold, 700);\n}\n\nblockquote {\n  border-left: 3px solid var(--border);\n  padding-left: 1rem;\n  font-style: italic;\n  color: var(--muted-foreground);\n  margin: 1.25rem 0;\n}\n\nhr {\n  height: 0;\n  color: inherit;\n  border-top-width: 1px;\n  border-color: var(--border);\n  margin: 1.5rem 0;\n}\n\n/* Links */\na {\n  color: inherit;\n  text-decoration: inherit;\n  cursor: pointer;\n  transition: color var(--duration-fast, 150ms) var(--ease-out, ease-out);\n}\n\na:hover {\n  text-decoration: underline;\n  text-underline-offset: 4px;\n}\n\n/* Code & Preformatted Text */\ncode,\nkbd,\nsamp,\npre {\n  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace);\n  font-size: 0.875em;\n}\n\ncode:not(pre code) {\n  background-color: var(--muted);\n  color: var(--foreground);\n  padding: 0.2em 0.4em;\n  border-radius: var(--radius-sm, 4px);\n  border: 1px solid var(--border);\n  white-space: break-spaces;\n}\n\npre {\n  background-color: var(--muted);\n  color: var(--foreground);\n  padding: 1rem;\n  border-radius: var(--radius-md, 6px);\n  overflow-x: auto;\n  border: 1px solid var(--border);\n  line-height: 1.45;\n  margin: 1rem 0;\n}\n\nkbd {\n  background-color: var(--muted);\n  border: 1px solid var(--border);\n  border-bottom-width: 2px;\n  border-radius: var(--radius-xs, 2px);\n  padding: 0.15em 0.35em;\n  font-size: 0.75em;\n  font-weight: var(--font-weight-medium, 500);\n  box-shadow: var(--shadow-2xs);\n}\n\n/* Selection Styling */\n::selection {\n  background-color: var(--primary);\n  color: var(--primary-foreground);\n}\n\n::-moz-selection {\n  background-color: var(--primary);\n  color: var(--primary-foreground);\n}\n\n/* Lists */\nol,\nul {\n  list-style: none;\n}\n\n/* Tables */\ntable {\n  border-collapse: collapse;\n  border-spacing: 0;\n  width: 100%;\n  text-indent: 0;\n  border-color: inherit;\n}\n\nth,\ntd {\n  padding: 0.75rem 1rem;\n  vertical-align: middle;\n  border-bottom: 1px solid var(--border);\n  text-align: left;\n}\n\nth {\n  font-weight: var(--font-weight-semibold, 600);\n  color: var(--foreground);\n}\n\n/* Media Elements */\nimg,\nsvg,\nvideo,\ncanvas,\naudio,\niframe,\nembed,\nobject {\n  display: block;\n  vertical-align: middle;\n  max-width: 100%;\n  height: auto;\n}\n\n/* Form Elements Reset */\nbutton,\ninput,\noptgroup,\nselect,\ntextarea {\n  font-family: inherit;\n  font-size: 100%;\n  font-weight: inherit;\n  line-height: inherit;\n  color: inherit;\n  margin: 0;\n  padding: 0;\n  background-color: transparent;\n  border-style: none;\n}\n\nbutton,\n[role=\"button\"] {\n  cursor: pointer;\n  user-select: none;\n}\n\nbutton:disabled,\ninput:disabled,\ntextarea:disabled,\nselect:disabled,\n[aria-disabled=\"true\"] {\n  cursor: var(--disabled-cursor, not-allowed);\n  opacity: var(--disabled-opacity, 0.5);\n  pointer-events: none;\n}\n\n/* Hidden elements */\n[hidden] {\n  display: none !important;\n}\n\n/* ==========================================================================\n   3. FOCUS-VISIBLE OUTLINE RINGS (ACCESSIBLE WCAG 2.2 AA / APCA)\n   ========================================================================== */\n\n/* Universal accessible keyboard focus ring */\n:focus-visible {\n  outline: var(--focus-ring-width, 2px) var(--focus-ring-style, solid) var(--focus-ring-color, var(--ring));\n  outline-offset: var(--focus-ring-offset, 2px);\n}\n\n/* Form control specific focus styling */\ninput:focus-visible,\ntextarea:focus-visible,\nselect:focus-visible {\n  outline: 2px solid var(--ring);\n  outline-offset: 0px;\n  border-color: var(--ring);\n}\n\n/* Remove default focus outline when not using keyboard navigation */\n:focus:not(:focus-visible) {\n  outline: none;\n}\n\n/* ==========================================================================\n   4. SCROLLBAR STYLING\n   ========================================================================== */\n\n/* Standards-compliant scrollbar styling */\nhtml,\nbody,\n* {\n  scrollbar-width: thin;\n  scrollbar-color: var(--border) transparent;\n}\n\n/* WebKit scrollbar styling */\n*::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n\n*::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n*::-webkit-scrollbar-thumb {\n  background-color: var(--border);\n  border-radius: var(--radius-full, 9999px);\n  border: 2px solid transparent;\n  background-clip: content-box;\n}\n\n*::-webkit-scrollbar-thumb:hover {\n  background-color: var(--muted-foreground);\n}\n\n*::-webkit-scrollbar-corner {\n  background: transparent;\n}\n\n/* ==========================================================================\n   5. REDUCED MOTION PREFERENCE OVERRIDE\n   ========================================================================== */\n\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n    scroll-behavior: auto !important;\n  }\n}\n",
