        "content": "/**\n * @plain-ui/tokens - index.css\n * \n * Complete bundle importing tokens, base reset & typography, and theme presets.\n */\n\n@import \"./tokens.css\";\n@import \"./base.css\";\n@import \"./themes.css\";\n",
