      {
        "name": "tokens.ts",
        "path": "tokens/index.ts",
        "content": "/**\n * @plain-ui/tokens - index.ts\n * \n * Programmatic access to Plain UI OKLCH tokens, themes, and accessibility utilities.\n */\n\nexport const THEME_NAMES = [\n  'zinc',\n  'violet',\n  'emerald',\n  'amber',\n  'rose',\n  'slate',\n  'stone',\n  'gray',\n  'neutral',\n  'blue',\n  'cyan',\n  'orange',\n] as const;\n\nexport type ThemeName = (typeof THEME_NAMES)[number];\n\nexport const PALETTES = [\n  'neutral',\n  'zinc',\n  'slate',\n  'stone',\n  'gray',\n  'violet',\n  'emerald',\n  'amber',\n  'rose',\n  'blue',\n  'green',\n  'red',\n  'cyan',\n  'orange',\n] as const;\nexport type PaletteName = (typeof PALETTES)[number];\n\nexport const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950] as const;\nexport type Shade = (typeof SHADES)[number];\n\nexport interface OKLCHColor {\n  l: number;\n  c: number;\n  h: number;\n  alpha?: number;\n}\n\nexport const SEMANTIC_TOKENS = [\n  'background',\n  'foreground',\n  'card',\n  'card-foreground',\n  'popover',\n  'popover-foreground',\n  'primary',\n  'primary-foreground',\n  'secondary',\n  'secondary-foreground',\n  'muted',\n  'muted-foreground',\n  'accent',\n  'accent-foreground',\n  'destructive',\n  'destructive-foreground',\n  'success',\n  'success-foreground',\n  'warning',\n  'warning-foreground',\n  'info',\n  'info-foreground',\n  'border',\n  'input',\n  'ring',\n  'radius',\n  'radius-sm',\n  'radius-md',\n  'radius-lg',\n  'radius-xl',\n] as const;\n\nexport type SemanticToken = (typeof SEMANTIC_TOKENS)[number];\n\n/**\n * Calculates WCAG 2.2 contrast ratio between two relative luminance values.\n */\nexport function getWcagContrast(lum1: number, lum2: number): number {\n  const brightest = Math.max(lum1, lum2);\n  const darkest = Math.min(lum1, lum2);\n  return (brightest + 0.05) / (darkest + 0.05);\n}\n\n/**\n * Validates WCAG 2.2 AA compliance.\n */\nexport function isWcagAACompliant(contrastRatio: number, isLargeText = false): boolean {\n  return isLargeText ? contrastRatio >= 3.0 : contrastRatio >= 4.5;\n}\n\n/**\n * Converts OKLCH color to standard sRGB array [r, g, b] (0-255).\n */\nexport function oklchToRgb(l: number, c: number, h: number): [number, number, number] {\n  const hRad = (h * Math.PI) / 180;\n  const a = c * Math.cos(hRad);\n  const b = c * Math.sin(hRad);\n\n  const l_ = l + 0.3963377774 * a + 0.2158037573 * b;\n  const m_ = l - 0.1055613458 * a - 0.0638541728 * b;\n  const s_ = l - 0.0894841775 * a - 1.2914855480 * b;\n\n  const L = l_ * l_ * l_;\n  const M = m_ * m_ * m_;\n  const S = s_ * s_ * s_;\n\n  const rLin = +4.0767416621 * L - 3.3077115913 * M + 0.2309699292 * S;\n  const gLin = -1.2684380046 * L + 2.6097574011 * M - 0.3413193965 * S;\n  const bLin = -0.0041960863 * L - 0.7034186147 * M + 1.7076147010 * S;\n\n  const gamma = (x: number) => {\n    const clamped = Math.max(0, Math.min(1, x));\n    return clamped <= 0.0031308 ? 12.92 * clamped : 1.055 * Math.pow(clamped, 1 / 2.4) - 0.055;\n  };\n\n  return [\n    Math.round(gamma(rLin) * 255),\n    Math.round(gamma(gLin) * 255),\n    Math.round(gamma(bLin) * 255),\n  ];\n}\n",
        "type": "registry:lib",
        "target": "src/styles/tokens.ts"
      }
